    misconceptions:[
      {wrong:'चक्रीय प्रकाश फॉस्फोरिलीकरण NADPH बनाता है।', right:'चक्रीय प्रवाह केवल ATP बनाता है। इलेक्ट्रॉन PS I पर लौटता है और पानी नहीं टूटता, इसलिए न NADPH न O<sub>2</sub>।'},
      {wrong:'Z योजना के अंत में PS II के खोए इलेक्ट्रॉन उसे लौट आते हैं।', right:'अचक्रीय मार्ग में इलेक्ट्रॉन लौटते नहीं; वे NADPH में समाप्त होते हैं। PS II पानी से नए इलेक्ट्रॉन पाता है।'},
      {wrong:'चक्रीय प्रकाश फॉस्फोरिलीकरण दोनों प्रकाश तंत्रों वाले ग्रैना थायलाकॉइड में होता है।', right:'माना जाता है कि यह PS II और NADP रिडक्टेज़ रहित स्ट्रोमा लैमेली में होता है।'}
    ],
    analogy:'Z योजना दो लिफ़्ट वाली वॉटर पार्क सवारी जैसी है: लिफ़्ट 1 (PS II) आपको ऊपर उठाती है, आप फिसलते हैं (इलेक्ट्रॉन परिवहन, ATP के लिए ऊर्जा), लिफ़्ट 2 (PS I) और ऊँचा उठाती है, और अंतिम फिसलन आपको पूल (NADP<sup>+</sup>) में गिराती है। चक्रीय प्रवाह में आप केवल लिफ़्ट 2 पर चढ़कर बार-बार उसी के नीचे फिसलते हैं।',
